import React from "react";

export function BorderBeam({
  className = "",
  size = 300,
  duration = 10,
  delay = 0,
  borderWidth = 1.5,
}) {
  return (
    <div
      className={`absolute inset-0 rounded-[3rem] overflow-hidden pointer-events-none ${className}`}
      style={{
        WebkitMaskImage: `radial-gradient(circle, transparent 50%, black 100%)`,
        maskImage: `radial-gradient(circle, transparent 50%, black 100%)`,
      }}
    >
      <div
        className="absolute h-full w-full bg-gradient-to-r"
        style={{
          background: `conic-gradient(from var(--angle), var(--color-1) 0deg, var(--color-2) 90deg, var(--color-3) 180deg, var(--color-4) 270deg, var(--color-1) 360deg)`,
          "--angle": "0deg",
          "--color-1": "rgb(0, 0, 0, 0)",
          "--color-2": "rgb(239, 68, 68)",
          "--color-3": "rgb(0, 0, 0, 0)",
          "--color-4": "rgb(59, 130, 246)",
          animation: `borderBeamAnimation ${duration}s linear infinite`,
          animationDelay: `${delay}s`,
          width: `${size}px`,
          height: `${size}px`,
          borderWidth: `${borderWidth}px`,
          borderStyle: "solid",
          borderColor: "transparent",
          borderImage: "linear-gradient(45deg, transparent, rgba(239, 68, 68, 0.6), transparent) 1",
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
        }}
      />
    </div>
  );
}

// Add keyframes to your CSS or use this styled version
const style = document.createElement("style");
style.textContent = `
  @keyframes borderBeamAnimation {
    0% {
      transform: rotate(0deg) translateX(0);
    }
    100% {
      transform: rotate(360deg) translateX(0);
    }
  }
`;
if (typeof document !== "undefined") {
  document.head.appendChild(style);
}
